interface CheckoutStatusBarState {
	readonly isCheckoutRunning: boolean;
	readonly isCommitRunning: boolean;
	readonly isSyncRunning: boolean;
}

class CheckoutStatusBar {

	private a = new EventEmitter<void>();
	get onDidChange(): Event<void> { return this.a.event; }
	private b: Disposable[] = [];

	private f: CheckoutStatusBarState;
	private get g() { return this.f; }
	private set g(state: CheckoutStatusBarState) {
		this.f = state;
		this.a.fire();
	}

	constructor(private h: $Smc) {
		this.f = {
			isCheckoutRunning: false,
			isCommitRunning: false,
			isSyncRunning: false
		};

		h.onDidChangeOperations(this.k, this, this.b);
		h.onDidRunGitStatus(this.a.fire, this.a, this.b);
		h.onDidChangeBranchProtection(this.a.fire, this.a, this.b);
	}

	get command(): Command | undefined {
		const operationData = [
			...this.h.operations.getOperations(OperationKind.Checkout) as CheckoutOperation[],
			...this.h.operations.getOperations(OperationKind.CheckoutTracking) as CheckoutTrackingOperation[]
		];

		const rebasing = !!this.h.rebaseCommit;
		const label = operationData[0]?.refLabel ?? `${this.h.headLabel}${rebasing ? ` (${l10n.t('Rebasing')})` : ''}`;
		const command = (this.g.isCheckoutRunning || this.g.isCommitRunning || this.g.isSyncRunning) ? '' : 'git.checkout';

		return {
			command,
			tooltip: `${label}, ${this.j()}`,
			title: `${this.i()} ${label}`,
			arguments: [this.h.sourceControl]
		};
	}

	private i(): string {
		if (!this.h.HEAD) {
			return '';
		}

		// Checkout
		if (this.g.isCheckoutRunning) {
			return '$(loading~spin)';
		}

		// Branch
		if (this.h.HEAD.type === RefType.Head && this.h.HEAD.name) {
			return this.h.isBranchProtected() ? '$(lock)' : '$(git-branch)';
		}

		// Tag
		if (this.h.HEAD.type === RefType.Tag) {
			return '$(tag)';
		}

		// Commit
		return '$(git-commit)';
	}

	private j(): string {
		if (this.g.isCheckoutRunning) {
			return l10n.t('Checking Out Branch/Tag...');
		}

		if (this.g.isCommitRunning) {
			return l10n.t('Committing Changes...');

		}

		if (this.g.isSyncRunning) {
			return l10n.t('Synchronizing Changes...');
		}

		return l10n.t('Checkout Branch/Tag...');
	}

	private k(): void {
		const isCommitRunning = this.h.operations.isRunning(OperationKind.Commit);
		const isCheckoutRunning = this.h.operations.isRunning(OperationKind.Checkout) ||
			this.h.operations.isRunning(OperationKind.CheckoutTracking);
		const isSyncRunning = this.h.operations.isRunning(OperationKind.Sync) ||
			this.h.operations.isRunning(OperationKind.Push) ||
			this.h.operations.isRunning(OperationKind.Pull);

		this.g = { ...this.g, isCheckoutRunning, isCommitRunning, isSyncRunning };
	}

	dispose(): void {
		this.b.forEach(d => d.dispose());
	}
}

interface SyncStatusBarState {
	readonly enabled: boolean;
	readonly isCheckoutRunning: boolean;
	readonly isCommitRunning: boolean;
	readonly isSyncRunning: boolean;
	readonly hasRemotes: boolean;
	readonly HEAD: Branch | undefined;
	readonly remoteSourcePublishers: RemoteSourcePublisher[];
}

class SyncStatusBar {

	private a = new EventEmitter<void>();
	get onDidChange(): Event<void> { return this.a.event; }
	private b: Disposable[] = [];

	private f: SyncStatusBarState;
	private get g() { return this.f; }
	private set g(state: SyncStatusBarState) {
		this.f = state;
		this.a.fire();
	}

	constructor(private h: $Smc, private i: IRemoteSourcePublisherRegistry) {
		this.f = {
			enabled: true,
			isCheckoutRunning: false,
			isCommitRunning: false,
			isSyncRunning: false,
			hasRemotes: false,
			HEAD: undefined,
			remoteSourcePublishers: i.getRemoteSourcePublishers()
		};

		h.onDidRunGitStatus(this.l, this, this.b);
		h.onDidChangeOperations(this.k, this, this.b);

		$Wlc(i.onDidAddRemoteSourcePublisher, i.onDidRemoveRemoteSourcePublisher)
			(this.m, this, this.b);

		const onEnablementChange = $Vlc(workspace.onDidChangeConfiguration, e => e.affectsConfiguration('git.enableStatusBarSync'));
		onEnablementChange(this.j, this, this.b);
		this.j();
	}

	private j(): void {
		const config = workspace.getConfiguration('git', Uri.file(this.h.root));
		const enabled = config.get<boolean>('enableStatusBarSync', true);

		this.g = { ... this.g, enabled };
	}

	private k(): void {
		const isCommitRunning = this.h.operations.isRunning(OperationKind.Commit);
		const isCheckoutRunning = this.h.operations.isRunning(OperationKind.Checkout) ||
			this.h.operations.isRunning(OperationKind.CheckoutTracking);
		const isSyncRunning = this.h.operations.isRunning(OperationKind.Sync) ||
			this.h.operations.isRunning(OperationKind.Push) ||
			this.h.operations.isRunning(OperationKind.Pull);

		this.g = { ...this.g, isCheckoutRunning, isCommitRunning, isSyncRunning };
	}

	private l(): void {
		this.g = {
			...this.g,
			hasRemotes: this.h.remotes.length > 0,
			HEAD: this.h.HEAD
		};
	}

	private m(): void {
		this.g = {
			...this.g,
			remoteSourcePublishers: this.i.getRemoteSourcePublishers()
		};
	}

	get command(): Command | undefined {
		if (!this.g.enabled) {
			return;
		}

		if (!this.g.hasRemotes) {
			if (this.g.remoteSourcePublishers.length === 0) {
				return;
			}

			const command = (this.g.isCheckoutRunning || this.g.isCommitRunning) ? '' : 'git.publish';
			const tooltip =
				this.g.isCheckoutRunning ? l10n.t('Checking Out Changes...') :
					this.g.isCommitRunning ? l10n.t('Committing Changes...') :
						this.g.remoteSourcePublishers.length === 1
							? l10n.t('Publish to {0}', this.g.remoteSourcePublishers[0].name)
							: l10n.t('Publish to...');

			return {
				command,
				title: `$(cloud-upload)`,
				tooltip,
				arguments: [this.h.sourceControl]
			};
		}

		const HEAD = this.g.HEAD;
		let icon = '$(sync)';
		let text = '';
		let command = '';
		let tooltip = '';

		if (HEAD && HEAD.name && HEAD.commit) {
			if (HEAD.upstream) {
				if (HEAD.ahead || HEAD.behind) {
					text += this.h.syncLabel;
				}

				command = 'git.sync';
				tooltip = this.h.syncTooltip;
			} else {
				icon = '$(cloud-upload)';
				command = 'git.publish';
				tooltip = l10n.t('Publish Branch');
			}
		} else {
			command = '';
			tooltip = '';
		}

		if (this.g.isCheckoutRunning) {
			command = '';
			tooltip = l10n.t('Checking Out Changes...');
		}

		if (this.g.isCommitRunning) {
			command = '';
			tooltip = l10n.t('Committing Changes...');
		}

		if (this.g.isSyncRunning) {
			icon = '$(sync~spin)';
			command = '';
			tooltip = l10n.t('Synchronizing Changes...');
		}

		return {
			command,
			title: [icon, text].join(' ').trim(),
			tooltip,
			arguments: [this.h.sourceControl]
		};
	}

	dispose(): void {
		this.b.forEach(d => d.dispose());
	}
}

export class $vmc {

	readonly onDidChange: Event<void>;

	private a: SyncStatusBar;
	private b: CheckoutStatusBar;
	private f: Disposable[] = [];

	constructor(repository: $Smc, remoteSourcePublisherRegistry: IRemoteSourcePublisherRegistry) {
		this.a = new SyncStatusBar(repository, remoteSourcePublisherRegistry);
		this.b = new CheckoutStatusBar(repository);
		this.onDidChange = $Wlc(this.a.onDidChange, this.b.onDidChange);
	}

	get commands(): Command[] {
		return [this.b.command, this.a.command]
			.filter((c): c is Command => !!c);
	}

	dispose(): void {
		this.a.dispose();
		this.b.dispose();
		this.f = $Plc(this.f);
	}
}
