import { PickRemoteSourceOptions, PickRemoteSourceResult } from './api/git-base';
import { $Jmc } from './git-base';

export async function $dnc(options: PickRemoteSourceOptions & { branch?: false | undefined }): Promise<string | undefined>;
export async function $dnc(options: PickRemoteSourceOptions & { branch: true }): Promise<PickRemoteSourceResult | undefined>;
export async function $dnc(options: PickRemoteSourceOptions = {}): Promise<string | PickRemoteSourceResult | undefined> {
	return $Jmc.getAPI().pickRemoteSource(options);
}

export async function $enc(url: string) {
	return $Jmc.getAPI().getRemoteSourceActions(url);
}
