import { $Gmc } from '../model';
import { GitExtension, Repository, API } from './git';
import { $Nmc, $Pmc } from './api1';
import { Event, EventEmitter } from 'vscode';

export function $Hmc(_target: any, key: string, descriptor: any): void {
	if (typeof descriptor.value !== 'function') {
		throw new Error('not supported');
	}

	const fn = descriptor.value;
	descriptor.value = function () {
		console.warn(`Git extension API method '${key}' is deprecated.`);
		return fn.apply(this, arguments);
	};
}

export class $Imc implements GitExtension {

	enabled: boolean = false;

	private a = new EventEmitter<boolean>();
	readonly onDidChangeEnablement: Event<boolean> = this.a.event;

	private b: $Gmc | undefined = undefined;

	set model(model: $Gmc | undefined) {
		this.b = model;

		const enabled = !!model;

		if (this.enabled === enabled) {
			return;
		}

		this.enabled = enabled;
		this.a.fire(this.enabled);
	}

	get model(): $Gmc | undefined {
		return this.b;
	}

	constructor(model?: $Gmc) {
		if (model) {
			this.enabled = true;
			this.b = model;
		}
	}

	@$Hmc
	async getGitPath(): Promise<string> {
		if (!this.b) {
			throw new Error('Git model not found');
		}

		return this.b.git.path;
	}

	@$Hmc
	async getRepositories(): Promise<Repository[]> {
		if (!this.b) {
			throw new Error('Git model not found');
		}

		return this.b.repositories.map(repository => new $Nmc(repository));
	}

	getAPI(version: number): API {
		if (!this.b) {
			throw new Error('Git model not found');
		}

		if (version !== 1) {
			throw new Error(`No API version ${version} found.`);
		}

		return new $Pmc(this.b);
	}
}
