	private async ib<T>(runOperation: () => Promise<T>): Promise<T> {
		const config = workspace.getConfiguration('git', Uri.file(this.root));
		const shouldAutoStash = config.get<boolean>('autoStash')
			&& this.workingTreeGroup.resourceStates.some(r => r.type !== Status.UNTRACKED && r.type !== Status.IGNORED);

		if (!shouldAutoStash) {
			return await runOperation();
		}

		await this.K.createStash(undefined, true);
		const result = await runOperation();
		await this.K.popStash();

		return result;
	}

	private jb(_uri: Uri): void {
		const config = workspace.getConfiguration('git');
		const autorefresh = config.get<boolean>('autorefresh');

		if (!autorefresh) {
			this.N.trace('Skip running git status because autorefresh setting is disabled.');
			return;
		}

		if (this.D) {
			this.N.trace('Skip running git status because repository is huge.');
			return;
		}

		if (!this.operations.isIdle()) {
			this.N.trace('Skip running git status because an operation is running.');
			return;
		}

		this.kb();
	}

