import { workspace, Uri, Disposable, Event, EventEmitter, window, FileSystemProvider, FileChangeEvent, FileStat, FileType, FileChangeType, FileSystemError } from 'vscode';
import { $jmc, $hmc } from './decorators';
import { $xmc, $ymc } from './uri';
import { $Gmc, ModelChangeEvent, OriginalResourceChangeEvent } from './model';
import { $Vlc, $1lc, $_lc, $amc, $Slc } from './util';
import { $Smc } from './repository';

interface CacheRow {
	uri: Uri;
	timestamp: number;
}

const THREE_MINUTES = 1000 * 60 * 3;
const FIVE_MINUTES = 1000 * 60 * 5;

function sanitizeRef(ref: string, path: string, repository: $Smc): string {
	if (ref === '~') {
		const fileUri = Uri.file(path);
		const uriString = fileUri.toString();
		const [indexStatus] = repository.indexGroup.resourceStates.filter(r => r.resourceUri.toString() === uriString);
		return indexStatus ? '' : 'HEAD';
	}

	if (/^~\d$/.test(ref)) {
		return `:${ref[1]}`;
	}

	return ref;
}

export class $3mc implements FileSystemProvider {

	private a = new EventEmitter<FileChangeEvent[]>();
	readonly onDidChangeFile: Event<FileChangeEvent[]> = this.a.event;

	private b = new Set<string>();
	private c = new Map<string, CacheRow>();
	private f = new Date().getTime();
	private g: Disposable[] = [];

	constructor(private h: $Gmc) {
		this.g.push(
			h.onDidChangeRepository(this.i, this),
			h.onDidChangeOriginalResource(this.j, this),
			workspace.registerFileSystemProvider('git', this, { isReadonly: true, isCaseSensitive: true }),
		);

		setInterval(() => this.m(), FIVE_MINUTES);
	}

	private i({ repository }: ModelChangeEvent): void {
		this.b.add(repository.root);
		this.k();
	}

	private j({ uri }: OriginalResourceChangeEvent): void {
		if (uri.scheme !== 'file') {
			return;
		}

		const gitUri = $ymc(uri, '', { replaceFileExtension: true });
		this.f = new Date().getTime();
		this.a.fire([{ type: FileChangeType.Changed, uri: gitUri }]);
	}

	@$jmc(1100)
	private k(): void {
		this.l();
	}

	@$hmc
	private async l(): Promise<void> {
		if (!window.state.focused) {
			const onDidFocusWindow = $Vlc(window.onDidChangeWindowState, e => e.focused);
			await $1lc(onDidFocusWindow);
		}

		const events: FileChangeEvent[] = [];

		for (const { uri } of this.c.values()) {
			const fsPath = uri.fsPath;

			for (const root of this.b) {
				if ($_lc(root, fsPath)) {
					events.push({ type: FileChangeType.Changed, uri });
					break;
				}
			}
		}

		if (events.length > 0) {
			this.f = new Date().getTime();
			this.a.fire(events);
		}

		this.b.clear();
	}

	private m(): void {
		const now = new Date().getTime();
		const cache = new Map<string, CacheRow>();

		for (const row of this.c.values()) {
			const { path } = $xmc(row.uri);
			const isOpen = workspace.textDocuments
				.filter(d => d.uri.scheme === 'file')
				.some(d => $amc(d.uri.fsPath, path));

			if (isOpen || now - row.timestamp < THREE_MINUTES) {
				cache.set(row.uri.toString(), row);
			} else {
				// TODO: should fire delete events?
			}
		}

		this.c = cache;
	}

	watch(): Disposable {
		return $Slc;
	}

	async stat(uri: Uri): Promise<FileStat> {
		await this.h.isInitialized;

		const { submoduleOf, path, ref } = $xmc(uri);
		const repository = submoduleOf ? this.h.getRepository(submoduleOf) : this.h.getRepository(uri);
		if (!repository) {
			throw FileSystemError.FileNotFound();
		}

		let size = 0;
		try {
			const details = await repository.getObjectDetails(sanitizeRef(ref, path, repository), path);
			size = details.size;
		} catch {
			// noop
		}
		return { type: FileType.File, size: size, mtime: this.f, ctime: 0 };
	}

	readDirectory(): Thenable<[string, FileType][]> {
		throw new Error('Method not implemented.');
	}

	createDirectory(): void {
		throw new Error('Method not implemented.');
	}

	async readFile(uri: Uri): Promise<Uint8Array> {
		await this.h.isInitialized;

		const { path, ref, submoduleOf } = $xmc(uri);

		if (submoduleOf) {
			const repository = this.h.getRepository(submoduleOf);

			if (!repository) {
				throw FileSystemError.FileNotFound();
			}

			const encoder = new TextEncoder();

			if (ref === 'index') {
				return encoder.encode(await repository.diffIndexWithHEAD(path));
			} else {
				return encoder.encode(await repository.diffWithHEAD(path));
			}
		}

		const repository = this.h.getRepository(uri);

		if (!repository) {
			throw FileSystemError.FileNotFound();
		}

		const timestamp = new Date().getTime();
		const cacheValue: CacheRow = { uri, timestamp };

		this.c.set(uri.toString(), cacheValue);

		try {
			return await repository.buffer(sanitizeRef(ref, path, repository), path);
		} catch (err) {
			return new Uint8Array(0);
		}
	}

	writeFile(): void {
		throw new Error('Method not implemented.');
	}

	delete(): void {
		throw new Error('Method not implemented.');
	}

	rename(): void {
		throw new Error('Method not implemented.');
	}

	dispose(): void {
		this.g.forEach(d => d.dispose());
	}
}
